// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   origin              → implicit (0,0,0), the three axes meet there
   axis inner y1/y2/y3 → CylinderGeometry shaft r=0.016, 0 → 1, #5A0F0F,
                         depthTest:false renderOrder 2 → reads solid dark maroon
                         ON TOP of the pink fill, as in the source
   axis outer y1/y2/y3 → CylinderGeometry shaft r=0.016, 1 → 1.42, #000000
   arrowheads          → ConeGeometry(0.062, 0.135) at 1.42 → 1.555, #000000
   simplex triangle    → BufferGeometry 3 verts (1,0,0)(0,1,0)(0,0,1),
                         MeshBasicMaterial #F7B3B3 op .74 DoubleSide, no depthWrite
   marker              → SphereGeometry(0.05) #B11226  (draggable)
   marker pick volume  → SphereGeometry(0.14) invisible
   vertex pick spheres → SphereGeometry(0.11) invisible at each unit point
   guide lines (x3)    → Line, LineDashedMaterial #B11226, marker → axis foot
   labels              → HTML sprites: y1,y2,y3 (22px italic serif);
                         1,1,1 (21px serif); Car, Bike, Bird (20px bold sans)
 ─────────────────────────────────────────────────────────────────────────── */

const SIMPLEX = new THREE.Group();
scene.add(SIMPLEX);

const C_MAROON = 0x5A0F0F;
const C_BLACK  = 0x000000;
const C_PINK   = 0xF7B3B3;
const C_RED    = 0xB11226;

const AX_DIR = [
  new THREE.Vector3(1, 0, 0),   // y1 → +X (screen right)
  new THREE.Vector3(0, 1, 0),   // y2 → +Y (screen up)
  new THREE.Vector3(0, 0, 1)    // y3 → +Z (projects down-left, toward viewer)
];
const VERT = AX_DIR.map(v => v.clone());

const SHAFT_R = 0.016;
const HEAD_R  = 0.062;
const HEAD_L  = 0.135;
const SHAFT_END = 1.42;
const TIP = SHAFT_END + HEAD_L;

/* ---- geometry helpers ---------------------------------------------------- */
function makeShaft(a, b, color, radius, overlay) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, len, 16);
  geo.translate(0, len / 2, 0);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  if (overlay) { mat.depthTest = false; mat.depthWrite = false; }
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.copy(a);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}
function makeCone(base, dir, color) {
  const geo = new THREE.ConeGeometry(HEAD_R, HEAD_L, 20);
  geo.translate(0, HEAD_L / 2, 0);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 }));
  mesh.position.copy(base);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}
function invisibleMat() {
  return new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
}

/* ---- axes ---------------------------------------------------------------- */
const outerParts = [];          // faded in the flat-on view
const O = new THREE.Vector3(0, 0, 0);
AX_DIR.forEach(dir => {
  // inner maroon stretch: drawn AFTER / OVER the pink triangle
  const inner = makeShaft(O, dir.clone().multiplyScalar(1.0), C_MAROON, SHAFT_R, true);
  inner.renderOrder = 2;
  SIMPLEX.add(inner);

  const outer = makeShaft(dir.clone().multiplyScalar(1.0), dir.clone().multiplyScalar(SHAFT_END), C_BLACK, SHAFT_R, false);
  SIMPLEX.add(outer); outerParts.push(outer);

  const head = makeCone(dir.clone().multiplyScalar(SHAFT_END), dir, C_BLACK);
  SIMPLEX.add(head); outerParts.push(head);
});

/* ---- pink simplex triangle ----------------------------------------------- */
const triGeo = new THREE.BufferGeometry();
triGeo.setAttribute('position', new THREE.Float32BufferAttribute(
  [1, 0, 0, 0, 1, 0, 0, 0, 1], 3));
triGeo.computeVertexNormals();
const triMesh = new THREE.Mesh(triGeo, new THREE.MeshBasicMaterial({
  color: C_PINK, transparent: true, opacity: 0.74,
  side: THREE.DoubleSide, depthWrite: false
}));
triMesh.renderOrder = 1;
SIMPLEX.add(triMesh);
registerInteractive(triMesh, {
  title: 'The probability simplex',
  tooltip: 'The admissible set: y ≥ 0, y₁+y₂+y₃ = 1',
  body: 'Every admissible output of a 3-class classifier lies on this flat triangle: all three scores are non-negative and they sum to exactly 1. It is a 2-dimensional surface (K−1 = 2 degrees of freedom) sitting inside 3-dimensional score space.'
});

/* ---- draggable marker ---------------------------------------------------- */
const marker = new THREE.Mesh(
  new THREE.SphereGeometry(0.05, 24, 16),
  new THREE.MeshBasicMaterial({ color: C_RED, depthTest: false })
);
marker.renderOrder = 5;
SIMPLEX.add(marker);
const markerPick = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 10), invisibleMat());
marker.add(markerPick);
registerInteractive(marker, {
  title: 'A score vector y',
  tooltip: 'Drag me across the triangle',
  body: 'This marker is the classifier’s output for one image. Wherever you drag it on the triangle, y₁ + y₂ + y₃ stays exactly 1 — confidence can only be traded between Car, Bike and Bird, never created.'
});

/* ---- guide lines --------------------------------------------------------- */
const guides = AX_DIR.map(() => {
  const g = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]),
    new THREE.LineDashedMaterial({ color: C_RED, transparent: true, opacity: 0.55, dashSize: 0.05, gapSize: 0.035, depthTest: false })
  );
  g.renderOrder = 4;
  SIMPLEX.add(g);
  return g;
});
const feetDots = AX_DIR.map(() => {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.022, 12, 10),
    new THREE.MeshBasicMaterial({ color: C_RED, transparent: true, opacity: 0.85, depthTest: false }));
  m.renderOrder = 5; SIMPLEX.add(m); return m;
});

/* ---- vertex pick spheres ------------------------------------------------- */
const CLASS_NAMES = ['Car', 'Bike', 'Bird'];
VERT.forEach((v, i) => {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.12, 12, 10), invisibleMat());
  s.position.copy(v);
  SIMPLEX.add(s);
  registerInteractive(s, {
    title: `${CLASS_NAMES[i]} — vertex e${i + 1}`,
    tooltip: `Click: snap to ${CLASS_NAMES[i]} (one-hot)`,
    body: `At this corner the score vector is one-hot: y${i + 1} = 1 and the other two coordinates are 0. That is an unambiguous, fully-confident prediction of “${CLASS_NAMES[i]}”. Everything strictly inside the triangle is a graded mixture of the three classes.`,
    onClick: () => tweenTo(oneHot(i))
  });
});

/* ---- point state & math -------------------------------------------------- */
let Y = [1 / 3, 1 / 3, 1 / 3];

function oneHot(i) { const a = [0, 0, 0]; a[i] = 1; return a; }

// Euclidean projection of a 3-vector onto {y ≥ 0, Σy = 1}
function projectToSimplex(v) {
  const u = v.slice().sort((a, b) => b - a);
  let css = 0, theta = 0;
  for (let j = 0; j < 3; j++) {
    css += u[j];
    const t = (css - 1) / (j + 1);
    if (u[j] - t > 0) theta = t;
  }
  const out = v.map(x => Math.max(x - theta, 0));
  const s = out[0] + out[1] + out[2];
  return s > 1e-9 ? out.map(x => x / s) : [1 / 3, 1 / 3, 1 / 3];
}

function setPoint(y) {
  Y = y;
  marker.position.set(Y[0], Y[1], Y[2]);
  const feet = [
    new THREE.Vector3(Y[0], 0, 0),
    new THREE.Vector3(0, Y[1], 0),
    new THREE.Vector3(0, 0, Y[2])
  ];
  guides.forEach((g, i) => {
    g.geometry.dispose();
    g.geometry = new THREE.BufferGeometry().setFromPoints([marker.position.clone(), feet[i]]);
    g.computeLineDistances();
    feetDots[i].position.copy(feet[i]);
  });
  document.getElementById('ro1').textContent = Y[0].toFixed(3);
  document.getElementById('ro2').textContent = Y[1].toFixed(3);
  document.getElementById('ro3').textContent = Y[2].toFixed(3);
  document.getElementById('roSum').textContent = (Y[0] + Y[1] + Y[2]).toFixed(3);
}
setPoint(Y);

/* ---- camera --------------------------------------------------------------
   Measured off the source: y1 leaves the origin nearly horizontal, y3 drops
   steeply down-left (~45°). x:10 / z:42 pushes the Bird axis much further
   down-left than before while keeping the triangle broad on screen.        */
const VIEW_3D = { projection: 'orthographic', axisScreenAngles: { x: 10, z: 42 }, rollDeg: 0, heightFraction: 0.78 };
const VIEW_FLAT = { projection: 'orthographic', azimuthDeg: 45, elevationDeg: 35.264389682754654, rollDeg: 0, heightFraction: 0.62 };
setCameraView(VIEW_3D);

/* ---- labels -------------------------------------------------------------- */
const serif = 'font-family:Georgia,\'Times New Roman\',serif;';
const TIPV = AX_DIR.map(d => d.clone().multiplyScalar(TIP + 0.06));
const axLabels = [
  addLabel(`<span style="${serif}font-style:italic">y</span><sub style="${serif}">1</sub>`,
    TIPV[0], { fontSize: '22px', offset: [30, 2] }),
  addLabel(`<span style="${serif}font-style:italic">y</span><sub style="${serif}">2</sub>`,
    TIPV[1], { fontSize: '22px', offset: [26, -12] }),
  addLabel(`<span style="${serif}font-style:italic">y</span><sub style="${serif}">3</sub>`,
    TIPV[2], { fontSize: '22px', offset: [-8, 28] })
];
// '1' tick numerals: above-left of the y1 point, left of the y2 point,
// above-left of the y3 point — exactly as printed.
const tickOffsets = [[-12, -26], [-22, -3], [-16, -26]];
VERT.forEach((v, i) =>
  addLabel(`<span style="${serif}">1</span>`, v, { fontSize: '21px', offset: tickOffsets[i] }));
// Bold class names: Car below-right, Bike right, Bird below-right.
const classOffsets = [[40, 30], [44, -6], [46, 28]];
CLASS_NAMES.forEach((n, i) =>
  addLabel(n, VERT[i], { fontSize: '20px', bold: true, offset: classOffsets[i] }));

/* ---- view mode ----------------------------------------------------------- */
let viewMode = '3D axes';
function fadeOuter(alpha) {
  outerParts.forEach(o => { o.material.opacity = alpha; });
  axLabels.forEach(l => { l.div.style.opacity = String(Math.max(alpha, 0.15)); });
}
function setViewMode(mode) {
  viewMode = mode;
  document.getElementById('btnView3D').classList.toggle('active', mode === '3D axes');
  document.getElementById('btnViewFlat').classList.toggle('active', mode !== '3D axes');
  if (mode === '3D axes') { fadeOuter(1); setCameraView(VIEW_3D); }
  else { fadeOuter(0.14); setCameraView(VIEW_FLAT); }
}
document.getElementById('btnView3D').onclick = () => setViewMode('3D axes');
document.getElementById('btnViewFlat').onclick = () => setViewMode('Flat-on simplex');

/* ---- guides toggle ------------------------------------------------------- */
document.getElementById('chkGuides').onchange = (e) => {
  const on = e.target.checked;
  guides.forEach(g => g.visible = on);
  feetDots.forEach(f => f.visible = on);
};

/* ---- snap buttons -------------------------------------------------------- */
document.getElementById('snapCar').onclick = () => tweenTo(oneHot(0));
document.getElementById('snapBike').onclick = () => tweenTo(oneHot(1));
document.getElementById('snapBird').onclick = () => tweenTo(oneHot(2));
document.getElementById('snapMid').onclick = () => tweenTo([1 / 3, 1 / 3, 1 / 3]);

/* ---- tweening ------------------------------------------------------------ */
let tween = null;
function tweenTo(target, dur = 350) {
  tween = { from: Y.slice(), to: target.slice(), t0: performance.now(), dur };
}
function tickTween() {
  requestAnimationFrame(tickTween);
  if (!tween) return;
  const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
  setPoint(projectToSimplex([0, 1, 2].map(i => tween.from[i] + (tween.to[i] - tween.from[i]) * e)));
  if (u >= 1) tween = null;
}
tickTween();

/* ---- dragging ------------------------------------------------------------ */
const dragPlane = new THREE.Plane(new THREE.Vector3(1, 1, 1).normalize(), -1 / Math.sqrt(3));
const _ray = new THREE.Raycaster();
const _ndc = new THREE.Vector2();
const _hit = new THREE.Vector3();
let dragging = false;

function ndcFrom(e) {
  const r = canvas.getBoundingClientRect();
  _ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (e) => {
  ndcFrom(e);
  _ray.setFromCamera(_ndc, camera);
  const hits = _ray.intersectObjects([marker, markerPick], true);
  if (hits.length) {
    dragging = true;
    tween = null;
    controls.enabled = false;
    canvas.setPointerCapture?.(e.pointerId);
  }
}, true);
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  ndcFrom(e);
  _ray.setFromCamera(_ndc, camera);
  if (_ray.ray.intersectPlane(dragPlane, _hit)) {
    setPoint(projectToSimplex([_hit.x, _hit.y, _hit.z]));
  }
}, true);
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

/* ---- guided demo --------------------------------------------------------- */
const STEPS = [
  {
    title: 'The constraint plane',
    narration: 'Three axes y₁, y₂, y₃ carry the scores for Car, Bike and Bird. The pink triangle joins the three unit points: every point on it has non-negative coordinates summing to 1.',
    run: () => { setViewMode('3D axes'); tweenTo([1 / 3, 1 / 3, 1 / 3]); }
  },
  {
    title: 'Mixtures inside',
    narration: 'Drag the marker around the interior. The readouts shift — more Car means less Bike and Bird — but the sum is pinned at 1, so confidence is only ever redistributed.',
    run: () => { setViewMode('3D axes'); tweenTo([0.60, 0.25, 0.15], 600); }
  },
  {
    title: 'Vertices are certain answers',
    narration: 'The point snaps to (1, 0, 0) and the other two coordinates collapse to zero: a corner of the simplex is an unambiguous single-class prediction.',
    run: () => { setViewMode('3D axes'); tweenTo(oneHot(0)); }
  },
  {
    title: 'Only two degrees of freedom',
    narration: 'Looking straight down onto the plane, the simplex is just a flat triangle: for K = 3 classes the output lives in a (K−1) = 2-dimensional set.',
    run: () => { setViewMode('Flat-on simplex'); tweenTo([0.5, 0.3, 0.2], 500); }
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narration;
  document.getElementById('stepIdx').textContent = `${stepIdx + 1}/${STEPS.length}`;
  s.run();
}
document.getElementById('stepPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('stepNext').onclick = () => goToStep((stepIdx + 1) % STEPS.length);
goToStep(0);
